import six


class Loader(object):
    def __init__(self):
        self.raw_parsed_traces = {'DL': '', 'UL': ''}

    def read_from_file(self, file_path):
        data = self._read_txt(file_path)

        direction = 'UL' if 'UL_WMP' in data else 'DL'
        self.raw_parsed_traces[direction] = data
        return self

    def _read_txt(self, file_path):
        with open(file_path) as fh:
            return six.ensure_text(fh.read())
